      .subtitle {
        max-width: 62ch;
        margin: 0;
        color: var(--muted);
        font-size: 1.05rem;
        line-height: 1.7;
      }

      .faq-list {
        display: grid;
        gap: 14px;
      }

      .example {
        background: var(--surface-strong);
        border: 1px solid var(--line);
        border-radius: var(--radius);
        overflow: hidden;
        box-shadow: 0 12px 34px rgba(36, 51, 87, 0.06);
      }

      .question {
        width: 100%;
        border: 0;
        background: transparent;
