        text-align: left;
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 16px;
        padding: 22px 24px;
        font: inherit;
        cursor: pointer;
      }

      .question:hover {
        background: rgba(79, 124, 255, 0.03);
      }

      .question:focus-visible {
        outline: 3px solid rgba(79, 124, 255, 0.35);
        outline-offset: -3px;
      }

      .question-text {
        font-size: 1.02rem;
        font-weight: 700;
        line-height: 1.4;
      }

      .icon {
        flex: 0 0 auto;
        width: 36px;
        height: 36px;
        border-radius: 999px;
        background: var(--accent-soft);
        color: var(--accent);
        display: grid;
        place-items: center;
        transition: transform 0.2s ease, background 0.2s ease;
