    <title>Cats FAQ</title>
    <style>
      :root {
        color-scheme: light;
        --bg: #f6f8fc;
        --surface: rgba(255, 255, 255, 0.86);
        --surface-strong: #ffffff;
        --text: #172033;
        --muted: #5d6b86;
        --line: rgba(23, 32, 51, 0.1);
        --accent: #4f7cff;
        --accent-soft: rgba(79, 124, 255, 0.1);
        --shadow: 0 24px 60px rgba(36, 51, 87, 0.12);
        --radius: 24px;
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
          "Segoe UI", sans-serif;
        background:
          radial-gradient(circle at top left, rgba(79, 124, 255, 0.18), transparent 32%),
          radial-gradient(circle at top right, rgba(255, 181, 71, 0.16), transparent 28%),
          var(--bg);
        color: var(--text);
        min-height: 100vh;
      }

      .app {
        width: min(980px, calc(100% - 32px));
        margin: 0 auto;
        padding: 48px 0 64px;
      }

      .hero {
        background: var(--surface);
        border: 1px solid var(--line);
        box-shadow: var(--shadow);
        backdrop-filter: blur(16px);
        border-radius: calc(var(--radius) + 8px);
        padding: 40px;
        margin-bottom: 24px;
      }

      .eyebrow {
        display: inline-flex;
        align-items: center;
        gap: 8px;
        padding: 8px 12px;
        border-radius: 999px;
        background: var(--accent-soft);
        color: var(--accent);
        font-size: 0.875rem;
        font-weight: 700;
        letter-spacing: 0.02em;
      }

      h1 {
        margin: 18px 0 12px;
        font-size: clamp(2.2rem, 4vw, 4rem);
        line-height: 1.02;
        letter-spacing: -0.05em;
      }

      .subtitle {
        max-width: 62ch;
        margin: 0;
        color: var(--muted);
        font-size: 1.05rem;
        line-height: 1.7;
      }

      .faq-list {
        display: grid;
        gap: 14px;
      }

      .example {
        background: var(--surface-strong);
        border: 1px solid var(--line);
        border-radius: var(--radius);
        overflow: hidden;
        box-shadow: 0 12px 34px rgba(36, 51, 87, 0.06);
      }

      .question {
        width: 100%;
        border: 0;
        background: transparent;
        color: inherit;
        text-align: left;
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 16px;
        padding: 22px 24px;
        font: inherit;
        cursor: pointer;
      }

      .question:hover {
        background: rgba(79, 124, 255, 0.03);
      }

      .question:focus-visible {
        outline: 3px solid rgba(79, 124, 255, 0.35);
        outline-offset: -3px;
      }

      .question-text {
        font-size: 1.02rem;
        font-weight: 700;
        line-height: 1.4;
      }

      .icon {
        flex: 0 0 auto;
        width: 36px;
        height: 36px;
        border-radius: 999px;
        background: var(--accent-soft);
        color: var(--accent);
        display: grid;
        place-items: center;
        transition: transform 0.2s ease, background 0.2s ease;
        font-size: 1.2rem;
      }

      .example.open .icon {
        transform: rotate(45deg);
        background: rgba(79, 124, 255, 0.16);
      }

      .details {
        max-height: 0;
        overflow: hidden;
        transition: max-height 0.28s ease;
        border-top: 1px solid transparent;
      }

      .example.open .details {
        border-top-color: var(--line);
      }

      .details-inner {
        padding: 0 24px 22px;
        color: var(--muted);
        line-height: 1.7;
      }

      .details p {
        margin: 0;
      }

      .details ul {
        margin: 12px 0 0;
        padding-left: 20px;
      }

      .details li + li {
        margin-top: 8px;
      }

      @media (max-width: 640px) {
        .app {
          width: min(100% - 20px, 980px);
          padding-top: 20px;
        }

        .hero {
          padding: 28px 20px;
        }

        .question {
          padding: 18px 18px;
        }

        .details-inner {
          padding: 0 18px 18px;
        }
      }
    </style>
  </head>
  <body>
    <main class="app" id="app"></main>

    <script>
      const faqs = [
        {
          question: "Why do cats purr?",
          answer:
            "Cats often purr when they are content, but they may also purr when they are nervous, in pain, or trying to soothe themselves. It is one of the simplest sounds they use to communicate comfort and need.",
        },
        {
          question: "How much sleep do cats need?",
          answer:
            "Most cats sleep between 12 and 16 hours a day. Kittens and older cats can sleep even more, which helps them conserve energy for short bursts of play, hunting behavior, and exploring.",
        },
        {
          question: "Do indoor cats need enrichment?",
          answer:
            "Yes. Indoor cats thrive with climbing spaces, puzzle feeders, scratching posts, and interactive play. Enrichment helps reduce boredom and supports healthy exercise and mental stimulation.",
        },
        {
          question: "Why do cats knead with their paws?",
          answer:
            "Kneading is a comforting behavior that starts in kittenhood. Adult cats may knead when they feel safe, relaxed, or especially affectionate. Some cats also knead before settling down to rest.",
        },
        {
          question: "What foods are unsafe for cats?",
          answer:
            "Common unsafe foods include chocolate, onions, garlic, grapes, raisins, alcohol, and anything with xylitol. If you're unsure about a food, check with a veterinarian before sharing it.",
        },
        {
          question: "How often should I groom my cat?",
          answer:
            "Short-haired cats usually benefit from weekly brushing, while long-haired cats may need grooming several times a week. Regular brushing reduces shedding, helps prevent mats, and gives you a chance to spot skin issues early.",
        },
      ];

      function QuestionItem({ question, answer, index }) {
        return `
          <div class="example" data-index="${index}">
            <button class="question" type="button" aria-expanded="false" aria-controls="faq-panel-${index}">
              <span class="question-text">${question}</span>
              <span class="icon" aria-hidden="true">+</span>
            </button>
            <div class="details" id="faq-panel-${index}" role="region" aria-label="${question}">
              <div class="details-inner">
                <p>${answer}</p>
              </div>
            </div>
          </div>
        `;
      }

      function FaqPage(items) {
        return `
          <section class="hero">
            <span class="eyebrow">Cats FAQ</span>
            <h1>Everything you wanted to know about cats.</h1>
            <p class="subtitle">
              A modern, easy-to-scan FAQ with expandable answers for quick reading and calmer
              decision-making.
            </p>
          </section>
          <section class="faq-list" aria-label="Frequently asked questions">
            ${items.map((item, index) => QuestionItem({ ...item, index })).join("")}
          </section>
        `;
      }

      function setPanelState(example, expanded) {
        const button = example.querySelector(".question");
        const panel = example.querySelector(".details");
        const inner = example.querySelector(".details-inner");

        example.classList.toggle("open", expanded);
        button.setAttribute("aria-expanded", String(expanded));
        panel.style.maxHeight = expanded ? `${inner.scrollHeight}px` : "0px";
      }

      function bindAccordion(root) {
        const items = Array.from(root.querySelectorAll(".example"));

        items.forEach((example) => {
          const button = example.querySelector(".question");
          const panel = example.querySelector(".details");
          const inner = example.querySelector(".details-inner");

          panel.style.maxHeight = "0px";

          button.addEventListener("click", () => {
            const expanded = button.getAttribute("aria-expanded") === "true";
            setPanelState(example, !expanded);
          });

          window.addEventListener("resize", () => {
            if (button.getAttribute("aria-expanded") === "true") {
              panel.style.maxHeight = `${inner.scrollHeight}px`;
            }
          });
        });
      }

      const app = document.getElementById("app");
      app.innerHTML = FaqPage(faqs);
      bindAccordion(app);
    </script>
  </body>
</html>
